#![cfg(feature="player")]
#[path="support/audio_transitions.rs"]mod transitions;
#[path="support/rational_audio_seek.rs"]mod rational;
use fvid::{audio::AudioStream,playback_aiff::{AiffAudioReader,Limits}};
use std::{io::Cursor,time::Duration,sync::{Arc,Mutex}};
use rational::{Packet,collect,exact};
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/aifc-g711-original-width")}
fn bytes(n:&str)->Vec<u8>{std::fs::read(root().join(n)).unwrap()}
fn manifest()->serde_json::Value{serde_json::from_slice(&bytes("manifest.json")).unwrap()}
fn cases()->Vec<serde_json::Value>{manifest()["cases"].as_array().unwrap().clone()}
fn open(c:&serde_json::Value)->AiffAudioReader{let data=bytes(c["file"].as_str().unwrap());AiffAudioReader::open(data.as_slice(),Limits::default()).unwrap()}
fn expected(c:&serde_json::Value,first:usize)->Vec<Packet>{let data=bytes(c["oracle"].as_str().unwrap());let channels=c["channels"].as_u64().unwrap()as u16;if first==256{return vec![];}vec![Packet{rate:8000,channels,num:first as u128,den:8000,data:data[first*usize::from(channels)*4..].to_vec()}]}
#[test]fn eight_bit_compatibility_and_short_video_controls(){for c in cases().into_iter().filter(|c|c["original_bits"]==8){exact(&collect(&mut open(&c)),&expected(&c,0),"8bit remains compatible");}let mut v=fvid::playback_native::NativeReader::software(Cursor::new(bytes("neutral-video.mp4")),32<<20).unwrap();for _ in 0..6{assert_eq!(v.read_frame_raw().unwrap().unwrap().into_rgb(32<<20).unwrap(),vec![130;16*16*3]);}assert!(v.read_frame_raw().unwrap().is_none());}
#[test]fn original_uncompressed_width_does_not_change_coded_stride_or_native_seek(){for c in cases(){let n=c["file"].as_str().unwrap();let mut r=open(&c);assert_eq!(r.bits_per_sample(),c["original_bits"].as_u64().unwrap()as u16);assert_eq!(r.duration(),Some(Duration::from_millis(32)));exact(&collect(&mut r),&expected(&c,0),n);for target in [-1,0,1,17,127,255,256,1000]{let first=target.clamp(0,256)as usize;let at=r.seek_to(target);assert_eq!(at,first as i64);assert_eq!(r.time_of(at),Duration::from_micros(first as u64*125));exact(&collect(&mut r),&expected(&c,first),n);}r.rewind();exact(&collect(&mut r),&expected(&c,0),"rewind");}}
#[test]fn actual_worker_accepts_original_width_without_changing_waveform(){use fvid::audio_thread::AudioPlayback;use transitions::{Capture,Trace,ended};for c in cases(){let wanted=expected(&c,1);let raw=Arc::new(Mutex::new(rational::RawTrace::default()));let captured=raw.clone();let trace=Arc::new(Mutex::new(Trace::default()));let mut worker=AudioPlayback::start(Box::new(open(&c)),move||Box::new(rational::RawCapture{inner:Capture::new(trace),raw:captured}));worker.seek(Duration::from_micros(125));worker.play();ended(&worker,worker.generation());let guard=raw.lock().unwrap();exact(&guard.packets,&wanted,c["file"].as_str().unwrap());assert_eq!(guard.anchors,vec![Duration::from_micros(125)]);}}
#[test]fn invalid_original_width_alignment_eof_and_limits_stay_strict(){for name in manifest()["invalid_original_sizes"].as_array().unwrap(){let data=bytes(name.as_str().unwrap());let error=AiffAudioReader::open(data.as_slice(),Limits::default()).err().expect("invalid original width must refuse");assert!(error.to_string().contains("G.711 original sample size must be 1..32"),"{error}");}let data=bytes("orphan-channel.aifc");let error=AiffAudioReader::open(data.as_slice(),Limits::default()).err().expect("orphan channel must refuse");assert!(error.to_string().contains("channel frame"),"{error}");let data=bytes("truncated-declared-tail.aifc");let mut r=AiffAudioReader::open(data.as_slice(),Limits::default()).unwrap();while r.next_packet().unwrap().is_some(){}assert!(r.validate_eof().unwrap_err().to_string().contains("payload is truncated"));let data=bytes("alaw-2ch-8bit.aifc");let mut limits=Limits::default();limits.data_bytes=511;let error=AiffAudioReader::open(data.as_slice(),limits).err().expect("coded bytes remain bounded");assert!(error.to_string().contains("sample run is over"),"{error}");}
